120	/**
121	 * Prefixes a relative path with the locale segment when needed.
122	 * - Leaves absolute URLs (http, mailto, tel, protocol-relative) untouched.
123	 * - Leaves non-root relative paths (e.g., "#section", "mailto:") untouched.
124	 * - For default locale, returns the original path.
125	 * - Avoids double-prefixing when the path is already localized for the same locale.
126	 */
127	export function withLocalePath(path: string, locale: AppLocale): string {
128	  if (!path) return path;
129	  // Skip absolute or protocol-relative URLs (e.g., http:, https:, mailto:, tel:, //cdn)
